 public sealed class MetroOfferPin:MaskableGraphic {void Update(){if(!(Studio.Profile?.ReducedMotion??false))SetVerticesDirty();}protected override void OnPopulateMesh(VertexHelper vh){vh.Clear();var r=rectTransform.rect;var p=r.center+Vector2.up*((Studio.Profile?.ReducedMotion??false)?0:Mathf.Sin(Time.unscaledTime*2.5f)*2);float s=Mathf.Min(r.width,r.height)*.45f;CraftedPanel.Diamond(vh,p,s,FlatUI.Hex("#FFD447"));CityGameSkin.Round(vh,new Rect(p.x-s*.2f,p.y-s*.2f,s*.8f,s*.4f),1,FlatUI.Hex("#503315"),FlatUI.Hex("#503315"));}}
 public sealed class MetroDayDial:MaskableGraphic {public Func<float> Read;void Update()=>SetVerticesDirty();protected override void OnPopulateMesh(VertexHelper vh){vh.Clear();var r=rectTransform.rect;var p=r.center;float radius=Mathf.Min(r.width,r.height)*.42f,progress=Read?.Invoke()??0;for(int i=0;i<32;i++){float a=(90-i*360f/32)*Mathf.Deg2Rad,b=(90-(i+1)*360f/32)*Mathf.Deg2Rad;CraftedPanel.Line(vh,p+new Vector2(Mathf.Cos(a),Mathf.Sin(a))*radius,p+new Vector2(Mathf.Cos(b),Mathf.Sin(b))*radius,2.5f,i/32f<progress?FlatUI.Hex("#76F0C6"):FlatUI.Hex("#466C82"));}}}
 public sealed class MetroGlyph:MaskableGraphic {public int Kind;public Color Tint=Color.white;protected override void OnPopulateMesh(VertexHelper vh){vh.Clear();var r=rectTransform.rect;var p=r.center;float s=Mathf.Min(r.width,r.height)*.4f;var c=Tint;if(Kind==0){CityGameSkin.Round(vh,new Rect(p.x-s*.35f,p.y+s*.1f,s*.7f,s*.7f),s*.35f,c,c);CityGameSkin.Round(vh,new Rect(p.x-s*.65f,p.y-s*.75f,s*1.3f,s*.8f),s*.2f,c,c);}else if(Kind==1){CityGameSkin.Round(vh,new Rect(p.x-s,p.y-s*.65f,s*2,s*1.3f),s*.2f,c,c);CraftedPanel.Line(vh,p+new Vector2(-s*.4f,s*.9f),p+new Vector2(s*.4f,s*.9f),s*.2f,c);}else if(Kind==2){CraftedPanel.Diamond(vh,p+Vector2.left*s*.4f,s*.55f,c);CraftedPanel.Line(vh,p,p+Vector2.right*s,s*.25f,c);CraftedPanel.Line(vh,p+Vector2.right*s*.7f,p+new Vector2(s*.7f,-s*.5f),s*.2f,c);}else if(Kind==3){CraftedPanel.Line(vh,p,p+Vector2.up*s*.6f,2,c);CraftedPanel.Line(vh,p,p+Vector2.right*s*.5f,2,c);}else if(Kind==4){for(int x=-1;x<=1;x+=2)for(int y=-1;y<=1;y+=2){var a=p+new Vector2(x,y)*s;CraftedPanel.Line(vh,a,a+Vector2.right*(-x*s*.6f),2,c);CraftedPanel.Line(vh,a,a+Vector2.up*(-y*s*.6f),2,c);}}else if(Kind==6){for(int i=0;i<5;i++){float a=(90+i*144)*Mathf.Deg2Rad,b=(90+(i+1)*144)*Mathf.Deg2Rad;CraftedPanel.Line(vh,p+new Vector2(Mathf.Cos(a),Mathf.Sin(a))*s,p+new Vector2(Mathf.Cos(b),Mathf.Sin(b))*s,2,c);}}else{CityGameSkin.Round(vh,new Rect(p.x-s,p.y-s*.65f,s*2,s*1.3f),s*.2f,c,c);CraftedPanel.Diamond(vh,p,s*.3f,FlatUI.Hex("#0C453B"));}}}
}
